import clsx from 'clsx';
import './AcidVideoText.css';

export interface AcidVideoTextProps {
    text: string;
    videoSrc: string;
    className?: string;
}

export const AcidVideoText = ({ text, videoSrc, className }: AcidVideoTextProps) => {
    return (
        <div className={clsx('ac-video-text-container', className)}>
            <video
                src={videoSrc}
                autoPlay
                muted
                loop
                playsInline
                className="ac-video-text-bg"
            />
            <h1 className="ac-video-text-mask">{text}</h1>
        </div>
    );
};

.ac-video-text-container {
    position: relative;
    width: 100%;
    height: 300px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #000;
    overflow: hidden;
}

.ac-video-text-bg {
    position: absolute;
    width: 100%;
    height: 100%;
    object-fit: cover;
    z-index: 1;
}

.ac-video-text-mask {
    position: relative;
    z-index: 2;
    font-size: 8rem;
    font-weight: 900;
    margin: 0;
    text-transform: uppercase;
    color: #000;
    background: #fff;
    mix-blend-mode: screen;
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
}
